{
  "world_id": "wld_dyson_swarm",
  "name": "The Penumbra Swarm",
  "description": "Eleven thousand habitats drift in staggered orbits around Ember, a red star slowly guttering out. Nobody alive remembers building the swarm. Its inhabitants inherited it, along with the ageing mirrors, tethers and light-collectors that keep it running. Ember dims by a measurable fraction every generation, so the swarm lives on a rationed calendar of shrinking light. Couriers carry cargo, letters and legal ledgers between habitats on solar-sail skiffs, and they are the only people who see the whole swarm. One courier finds a message from the builders. It is not written in any language. It is encoded in the pattern of shadows the habitats cast on one another, and the pattern is shifting. The tone is thoughtful and unhurried. The story asks what a civilization owes to the ancestors who made its home, and what it owes to descendants who will inherit a colder one.",
  "locations": [
    {
      "id": "loc_lantern_ring",
      "name": "Lantern Ring",
      "description": "The brightest and most crowded habitat belt, closest to Ember. Its rotating cylinders hold the swarm's governing assemblies and its central clock, which counts down the Dimming Calendar."
    },
    {
      "id": "loc_tether_market",
      "name": "Tether Market",
      "description": "A trading habitat strung between three counter-rotating hulls on kilometre-long cables. Couriers dock here to trade sail-cloth, messages and gossip, and the habitat is famously noisy."
    },
    {
      "id": "loc_quiet_shoal",
      "name": "The Quiet Shoal",
      "description": "A cluster of abandoned habitats in the outer swarm, left dark when their mirrors failed. The cold, silent hulls hold the oldest inscriptions anyone has found."
    },
    {
      "id": "loc_shadow_atrium",
      "name": "Shadow Atrium",
      "description": "A glass-roofed habitat where the passing shadows of neighbouring habitats are charted on the floor by a guild of observers. This is where the shifting pattern is first noticed."
    },
    {
      "id": "loc_seedvault_hollow",
      "name": "Seedvault Hollow",
      "description": "A habitat hollowed into a captured asteroid. It stores frozen seed stock and genetic archives against the day Ember fails, and it is guarded and politically sensitive."
    },
    {
      "id": "loc_first_node",
      "name": "First Node",
      "description": "A vast, featureless anchor structure at the swarm's gravitational heart. It predates every known habitat, and no door into it has ever opened."
    }
  ],
  "factions": [
    {
      "id": "fac_dimming_assembly",
      "name": "The Dimming Assembly",
      "description": "The governing body of Lantern Ring. It allocates light, orbit slots and mirror time, and it fears that any message from the builders could upset its carefully managed schedule of decline.",
      "location_ids": ["loc_lantern_ring", "loc_seedvault_hollow"]
    },
    {
      "id": "fac_courier_lodge",
      "name": "The Skiff Lodge",
      "description": "The independent guild of couriers. They hold a neutral status by custom and carry every habitat's messages without reading them, a tradition their oldest members call sacred.",
      "location_ids": ["loc_tether_market", "loc_quiet_shoal"]
    },
    {
      "id": "fac_shade_readers",
      "name": "The Shade Readers",
      "description": "Observers who chart shadow transits between habitats. They believe the swarm's orbits were designed to be read like text and to carry meaning beyond mere order.",
      "location_ids": ["loc_shadow_atrium", "loc_first_node"]
    },
    {
      "id": "fac_ember_heirs",
      "name": "Heirs of the Long Night",
      "description": "A movement that wants to abandon the swarm and carry its people toward a younger star. They see the builders as negligent and the message as a possible map or a possible warning.",
      "location_ids": ["loc_seedvault_hollow", "loc_tether_market"]
    }
  ],
  "rules": [
    {
      "id": "rul_ember_dimming",
      "statement": "Ember's output falls by a small, measurable fraction each generation, and no known technology can reverse this decline.",
      "category": "physics"
    },
    {
      "id": "rul_light_ration",
      "statement": "Every habitat holds a legal share of mirror light, and trading or stealing light shares is the gravest crime in the swarm.",
      "category": "social"
    },
    {
      "id": "rul_no_faster_travel",
      "statement": "No vessel exceeds the speed of light. A skiff crossing the swarm takes weeks, so all messages are slow and carry real physical weight.",
      "category": "physics"
    },
    {
      "id": "rul_unread_cargo",
      "statement": "A courier may never open or read what they carry, and breaking this custom ends their standing in the Skiff Lodge for life.",
      "category": "social"
    },
    {
      "id": "rul_orbit_drift",
      "statement": "Habitat orbits slowly drift, and the swarm needs constant small corrections to avoid collisions and shadow lock, where one habitat is permanently shaded by another.",
      "category": "technology"
    },
    {
      "id": "rul_builder_pattern",
      "statement": "The builders' message is carried by the changing shadow geometry of the swarm itself, so it can only be received by being physically present among the habitats and cannot be copied or transmitted.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_first_lighting",
      "name": "The First Lighting",
      "description": "The earliest recorded moment when the swarm's mirrors turned on and the habitats were first lit. Records do not say who did it.",
      "era": "Founding Age",
      "location_ids": ["loc_first_node"]
    },
    {
      "id": "evt_shoal_darkening",
      "name": "The Darkening of the Shoal",
      "description": "A cascade of mirror failures left a cluster of habitats permanently cold, and the survivors resettled in the inner ring and in bitter debt.",
      "era": "Age of Decline",
      "location_ids": ["loc_quiet_shoal", "loc_lantern_ring"]
    },
    {
      "id": "evt_light_accord",
      "name": "The Light Accord",
      "description": "After rationing riots, the habitats signed a compact fixing each one's legal share of mirror time and creating the Dimming Assembly.",
      "era": "Age of Decline",
      "location_ids": ["loc_lantern_ring", "loc_tether_market"]
    },
    {
      "id": "evt_shadow_charting",
      "name": "The Charting of Shadows",
      "description": "The Shade Readers began recording shadow transits as an astronomical craft and slowly noticed a pattern too regular to be accidental.",
      "era": "Age of Decline",
      "location_ids": ["loc_shadow_atrium"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_message_control",
      "name": "Who Owns the Message",
      "description": "The Assembly wants the builders' message suppressed or controlled, while the Shade Readers want it studied openly. The courier who found it is caught between them and the Lodge's duty of neutrality.",
      "faction_ids": ["fac_dimming_assembly", "fac_shade_readers", "fac_courier_lodge"]
    },
    {
      "id": "cnf_stay_or_leave",
      "name": "Stay or Depart",
      "description": "The Heirs of the Long Night want to evacuate the swarm toward another star, while the Assembly insists the habitats can be sustained. Each reads the builders' message as support for its own side.",
      "faction_ids": ["fac_ember_heirs", "fac_dimming_assembly"]
    }
  ]
}

